import{_ as a,o,c as e,a2 as i}from"./chunks/framework.DpXDHk3d.js";const u=JSON.parse('{"title":"2.3 串联与并联电路","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/02-chapter-2-dian-gong-ji-chu-zhi-shi/2-3-chuan-lian-yu-bing-lian-dian-lu.md","filePath":"electrician/low-voltage-electrician/02-chapter-2-dian-gong-ji-chu-zhi-shi/2-3-chuan-lian-yu-bing-lian-dian-lu.md","lastUpdated":1793095197000}'),l={name:"electrician/low-voltage-electrician/02-chapter-2-dian-gong-ji-chu-zhi-shi/2-3-chuan-lian-yu-bing-lian-dian-lu.md"};function n(r,t,s,d,c,h){return o(),e("div",null,[...t[0]||(t[0]=[i(`<h1 id="_2-3-串联与并联电路" tabindex="-1">2.3 串联与并联电路 <a class="header-anchor" href="#_2-3-串联与并联电路" aria-label="Permalink to &quot;2.3 串联与并联电路&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>电路里的元件怎么&quot;排队&quot;,决定了电流怎么走。<strong>串联</strong>和<strong>并联</strong>是两种最基本、也最重要的连接方式——家里的灯泡、开关、插座、电器,说到底都是这两种方式的组合。这一节把它们的规律讲透,并给出计算例题。</p><h2 id="一、串联电路-一个接一个-连成一串" tabindex="-1">一、串联电路:一个接一个,连成一串 <a class="header-anchor" href="#一、串联电路-一个接一个-连成一串" aria-label="Permalink to &quot;一、串联电路:一个接一个,连成一串&quot;">​</a></h2><p><strong>串联</strong>,就是元件<strong>首尾相接,连成一串</strong>,电流只有一条通路。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>───[R1]───[R2]───[R3]───</span></span></code></pre></div><h3 id="串联电路的三大规律" tabindex="-1">串联电路的三大规律 <a class="header-anchor" href="#串联电路的三大规律" aria-label="Permalink to &quot;串联电路的三大规律&quot;">​</a></h3><ol><li><strong>电流处处相等</strong>:<code>I = I1 = I2 = I3</code>——电流只有一条路,在哪儿都一样多。</li><li><strong>总电压等于各分电压之和</strong>:<code>U = U1 + U2 + U3</code>——电压被&quot;分着用&quot;。</li><li><strong>总电阻等于各电阻之和</strong>:<code>R = R1 + R2 + R3</code>——电阻越串越大。</li></ol><p><strong>分压原理</strong>:串联电路中,电阻大的元件分到的电压大。即 <code>U1 : U2 = R1 : R2</code>(电压按电阻成正比分配)。</p><blockquote><p>💡 <strong>水流类比</strong>:串联就像几段管子接成一长条,流量(电流)全程一样;但每一段管子的&quot;水压降&quot;(电压)加起来等于总水压。</p></blockquote><h2 id="二、并联电路-并排连接-各有各的路" tabindex="-1">二、并联电路:并排连接,各有各的路 <a class="header-anchor" href="#二、并联电路-并排连接-各有各的路" aria-label="Permalink to &quot;二、并联电路:并排连接,各有各的路&quot;">​</a></h2><p><strong>并联</strong>,就是元件<strong>并排连在两端之间</strong>,电流有多条通路。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>────┬─────[R1]────┬────</span></span>
<span class="line"><span>    ├─────[R2]────┤</span></span>
<span class="line"><span>    └─────[R3]────┘</span></span></code></pre></div><h3 id="并联电路的三大规律" tabindex="-1">并联电路的三大规律 <a class="header-anchor" href="#并联电路的三大规律" aria-label="Permalink to &quot;并联电路的三大规律&quot;">​</a></h3><ol><li><strong>电压处处相等</strong>:<code>U = U1 = U2 = U3</code>——两端之间电压相同。</li><li><strong>总电流等于各支路电流之和</strong>:<code>I = I1 + I2 + I3</code>——各支路分流后汇合。</li><li><strong>总电阻的倒数等于各支路电阻倒数之和</strong>:<code>1/R = 1/R1 + 1/R2 + 1/R3</code>——<strong>电阻越并越小</strong>。</li></ol><p><strong>分流原理</strong>:并联电路中,电阻小的支路分到的电流大。即 <code>I1 : I2 = R2 : R1</code>(电流按电阻成反比分配)。</p><blockquote><p>💡 <strong>水流类比</strong>:并联就像几根管子并排供水,每根管子两端的水压(电压)一样;但总流量(总电流)等于各根管子流量之和,管子越粗(电阻越小)流得越多。</p></blockquote><p><strong>两个电阻并联的快速公式</strong>(考试常用):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>R = R1·R2 / (R1 + R2)</span></span></code></pre></div><h2 id="三、串并联对比表-必背" tabindex="-1">三、串并联对比表(必背) <a class="header-anchor" href="#三、串并联对比表-必背" aria-label="Permalink to &quot;三、串并联对比表(必背)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>串联</th><th>并联</th></tr></thead><tbody><tr><td>连接方式</td><td>首尾相接</td><td>两端并接</td></tr><tr><td>电流</td><td>处处相等 I=I1=I2</td><td>总电流=各支路之和 I=I1+I2</td></tr><tr><td>电压</td><td>总电压=各分压之和 U=U1+U2</td><td>处处相等 U=U1=U2</td></tr><tr><td>总电阻</td><td>R=R1+R2(越串越大)</td><td>1/R=1/R1+1/R2(越并越小)</td></tr><tr><td>分配规律</td><td>电压按电阻成正比分压</td><td>电流按电阻成反比分流</td></tr><tr><td>一盏灯坏</td><td>整串全灭</td><td>其他支路仍工作</td></tr></tbody></table><h2 id="四、计算例题" tabindex="-1">四、计算例题 <a class="header-anchor" href="#四、计算例题" aria-label="Permalink to &quot;四、计算例题&quot;">​</a></h2><h3 id="例题-1-串联" tabindex="-1">例题 1(串联) <a class="header-anchor" href="#例题-1-串联" aria-label="Permalink to &quot;例题 1(串联)&quot;">​</a></h3><p>R1 = 2 Ω、R2 = 4 Ω 串联,接在 12 V 电源上。求:总电阻、总电流、R1 两端电压。</p><p><strong>解</strong>:</p><ul><li>总电阻 <code>R = R1 + R2 = 2 + 4 = 6 Ω</code></li><li>总电流 <code>I = U/R = 12/6 = 2 A</code>(串联电流处处相等)</li><li>R1 分压 <code>U1 = I·R1 = 2 × 2 = 4 V</code></li><li>验算:R2 分压 <code>U2 = I·R2 = 2 × 4 = 8 V</code>,<code>U1 + U2 = 12 V = U</code> ✓</li></ul><h3 id="例题-2-并联" tabindex="-1">例题 2(并联) <a class="header-anchor" href="#例题-2-并联" aria-label="Permalink to &quot;例题 2(并联)&quot;">​</a></h3><p>R1 = 4 Ω、R2 = 6 Ω 并联,接在 12 V 电源上。求:总电阻、各支路电流、总电流。</p><p><strong>解</strong>:</p><ul><li>总电阻 <code>R = R1·R2/(R1+R2) = 4×6/(4+6) = 24/10 = 2.4 Ω</code></li><li>R1 支路电流 <code>I1 = U/R1 = 12/4 = 3 A</code></li><li>R2 支路电流 <code>I2 = U/R2 = 12/6 = 2 A</code></li><li>总电流 <code>I = I1 + I2 = 3 + 2 = 5 A</code></li><li>验算:<code>I = U/R = 12/2.4 = 5 A</code> ✓</li></ul><h2 id="五、生活中的串并联" tabindex="-1">五、生活中的串并联 <a class="header-anchor" href="#五、生活中的串并联" aria-label="Permalink to &quot;五、生活中的串并联&quot;">​</a></h2><ul><li><strong>家用电器全是并联</strong>:插座之间、电器之间都并联接在 220 V 上,这样电压一样、互不影响(一个坏了其他还能用)。并联接法也是安全的要求——串联的话,一个开关就能控制整屋,而且各电器电压会分不均匀。</li><li><strong>串联的典型</strong>:节日小彩灯(一串)、电池串联(手电筒里两节电池正负极首尾相接提高电压)。</li></ul><h2 id="六、考点提示" tabindex="-1">六、考点提示 <a class="header-anchor" href="#六、考点提示" aria-label="Permalink to &quot;六、考点提示&quot;">​</a></h2><ul><li>✅ 串联:<strong>电流相等、电压相加、电阻相加</strong>;并联:<strong>电压相等、电流相加、电阻变小</strong>。</li><li>✅ 两电阻并联公式 <code>R = R1R2/(R1+R2)</code>,考试计算高频。</li><li>✅ 家用电器应该<strong>并联</strong>连接,不是串联。</li><li>⚠️ 易混点:串并联的&quot;分配&quot;方向相反——串联按电阻分电压(正比),并联按电阻分电流(反比)。</li></ul><h2 id="七、本节小结" tabindex="-1">七、本节小结 <a class="header-anchor" href="#七、本节小结" aria-label="Permalink to &quot;七、本节小结&quot;">​</a></h2><ul><li>串联:一条路,电流处处相等,总电阻变大,按电阻分压。</li><li>并联:多条路,电压处处相等,总电阻变小,按电阻分流。</li><li>计算遵循欧姆定律 + 串并联规律,先判连接方式再套公式。</li></ul><h2 id="八、自测练习" tabindex="-1">八、自测练习 <a class="header-anchor" href="#八、自测练习" aria-label="Permalink to &quot;八、自测练习&quot;">​</a></h2><ol><li>(判断)串联电路的总电阻等于各电阻之和,因此串联电路的电阻越串越大。( )</li><li>(判断)并联电路的总电流等于各支路电流之和。( )</li><li>(单选)两个 10 Ω 的电阻并联,总电阻是()。 A. 20 Ω　B. 10 Ω　C. 5 Ω　D. 2.5 Ω</li><li>(单选)串联电路中,电阻越大的元件()。 A. 分到的电压越大　B. 分到的电压越小　C. 电流越大　D. 不受影响</li><li>(单选)家用电器应当采用()连接。 A. 串联　B. 并联　C. 混联　D. 串并联均可</li><li>(计算)R1=3Ω、R2=6Ω 串联后接在 9V 电源上,求电路中的电流 I。</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>√</strong>。串联总电阻 = 各电阻之和,越串越大。</li><li><strong>√</strong>。并联总电流 = 各支路电流之和。</li><li><strong>C</strong>。并联公式 R = R1·R2/(R1+R2) = 10×10/20 = 5 Ω。</li><li><strong>A</strong>。串联按电阻成正比分压,电阻大的分到的电压大。</li><li><strong>B</strong>。家用电器必须并联,保证电压相同、互不影响。</li><li>总电阻 R = 3 + 6 = 9 Ω,电流 I = U/R = 9/9 = <strong>1 A</strong>。</li></ol></details>`,39)])])}const p=a(l,[["render",n]]);export{u as __pageData,p as default};
